kw = {'refund': ['refund', 'money back'], 'delivery': ['delivery', 'courier']}
def label(text):
    low = str(text).lower()
    for cat, words in kw.items():
        if any(w in low for w in words):
            return cat
    return 'other'

df['category'] = df['message'].astype(str).str.lower().map(label)

def validate(df, spec):
    problems = []
    for col, rules in spec.items():
        if col not in df.columns:
            problems.append(f'missing column {col}'); continue
        if rules.get('not_null') and df[col].isna().any():
            problems.append(f'{col} has nulls')
        lo, hi = rules.get('min'), rules.get('max')
        if lo is not None and (df[col] < lo).any(): problems.append(f'{col} below {lo}')
        if hi is not None and (df[col] > hi).any(): problems.append(f'{col} above {hi}')
    if problems: raise ValueError('; '.join(problems))
    return df
